import AppKit

/// Polls NSPasteboard.changeCount (macOS has no clipboard-change notification).
final class ClipboardMonitor {
    /// nspasteboard.org markers set by password managers (1Password, Bitwarden, KeePassXC...)
    private static let secret: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    ]

    private let pb = NSPasteboard.general
    private let store: ClipStore
    private let settings: Settings
    private var last: Int
    private var timer: Timer?

    init(store: ClipStore, settings: Settings) {
        self.store = store
        self.settings = settings
        last = pb.changeCount  // don't import whatever was copied before launch
    }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.4, repeats: true) { [weak self] _ in self?.poll() }
    }

    private func poll() {
        guard pb.changeCount != last else { return }
        last = pb.changeCount
        guard !settings.paused, last != store.ownChange else { return }
        if settings.ignoreSecrets, !Self.secret.isDisjoint(with: (pb.types ?? []).map(\.rawValue)) { return }

        if settings.recordText, let s = pb.string(forType: .string), !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            store.add(text: s)
        } else if settings.recordImages, let png = pb.data(forType: .png) {
            store.add(png: png)
        } else if settings.recordImages, let tiff = pb.data(forType: .tiff),
                  let png = NSBitmapImageRep(data: tiff)?.representation(using: .png, properties: [:]) {
            store.add(png: png)
        }
    }
}
